use corpse_core::{startup,temporal::Engine,Command};use serde_json::json;
fn main(){for mode in ["Unblessed","Blessed","Avatar"]{for seed in ["0-1-2:qa-normal-start","9-10-11:qa-normal-start"]{let result=(||{let mut r=startup::create_run_revision(seed,mode,false,38.)?;startup::ensure_floors(&mut r,40)?;let mut a=Engine::new(r).map_err(|e|e.to_string())?;let mut b=Engine::load(&a.save().map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;a.dispatch(&Command::Wait).map_err(|e|e.to_string())?;b.dispatch(&Command::Wait).map_err(|e|e.to_string())?;if a.save().unwrap()!=b.save().unwrap(){return Err("normal startup command nondeterminism".into())}Ok::<_,String>(())})();println!("{}",json!({"mode":mode,"seed":seed,"result":result}));}}}
